def write_all(stream, data):
    total_written = 0
    data_len = len(data)
    while total_written < data_len:
        bytes_written = stream.write(data[total_written:])
        if bytes_written == 0:
            raise BlockingIOError("Stream returned zero bytes written, indicating a blocking condition.")
        total_written += bytes_written
    return data_len

